function positionDAEContext(){
 const context=$('.dae-context'),map=$('.operations-map .map-wrap');if(!context||!map)return;
 const marker=map.querySelector('.ship-marker.active');if(!marker)return;
 const bounds=map.getBoundingClientRect(),ship=marker.getBoundingClientRect();
 const head=map.querySelector('.map-head'),headBounds=head?.getBoundingClientRect();
 const margin=12,topSafe=Math.max(margin,(headBounds?.bottom||bounds.top)-bounds.top+12);
 const height=Math.max(100,bounds.height-topSafe-52);
 context.style.setProperty('--context-height',height+'px');
 const width=context.offsetWidth,leftSide=ship.left-bounds.left-width-28,rightSide=ship.right-bounds.left+28;
 const preferred=leftSide>=margin?leftSide:rightSide;
 context.style.left=Math.max(margin,Math.min(preferred,bounds.width-width-margin))+'px';
 context.style.top=Math.max(topSafe,Math.min(ship.top-bounds.top-35,bounds.height-context.offsetHeight-48))+'px';
}
window.addEventListener('resize',positionDAEContext);
